/**
 * As ameaças do livro de regras (LR p. 182–289): as criaturas de cada elemento,
 * os animais e as pessoas, para o mestre escolher na ficha rápida do combate
 * (COMBATE.md, seção 17). Só nome, números e página: o texto das habilidades é
 * identidade do produto e fica no livro. Os números são os impressos, também
 * quando o livro parece errar (anotado em `duvida`).
 *
 * Lidas e conferidas em 30/09/2026, duas vezes cada, com o texto do PDF.
 * "Imune a dano" no livro = imune a todo dano (`todos`); nas criaturas de Medo,
 * isso cai quando o enigma de medo é resolvido (`enigma`).
 */
import type { Elemento, TipoDano } from '../regras/tipos';
import type { Tamanho } from './manobra';
import type { AtaqueAmeaca, TesteAmeaca } from './tipos';

export type AcaoAmeaca = 'padrao' | 'movimento' | 'completa' | 'livre' | 'reacao';

/** Outra ação ou reação da ficha, com os números (o que ela faz está no livro). */
export interface AcaoAmeacaLivro {
  acao: AcaoAmeaca;
  nome: string;
  teste?: TesteAmeaca;
  dt?: number;
  dano?: string;
  tipoDano?: TipoDano;
  /** o teste e o efeito, como no livro ("Fortitude reduz à metade") */
  resistencia?: string;
}

export interface AmeacaLivro {
  id: string;
  nome: string;
  /** página impressa do livro de regras */
  pagina: number;
  elemento?: Elemento;
  /** outros selos de elemento da ficha */
  outrosElementos?: Elemento[];
  /** descritor: Criatura, Pessoa, Animal... */
  tipo: string;
  tamanho: Tamanho;
  vd?: number;
  /** presença perturbadora: NEX que dá imunidade, DT e dano mental (LR p. 180) */
  presenca?: { nex: number; dt: number; dano: string };
  percepcao?: TesteAmeaca;
  iniciativa?: TesteAmeaca;
  sentidos: string[];
  defesa: number;
  fortitude: TesteAmeaca;
  reflexos: TesteAmeaca;
  vontade: TesteAmeaca;
  pv: number;
  machucado?: number;
  rd: Partial<Record<TipoDano, number>>;
  imunidades: TipoDano[];
  /** imunidade a condições e outros efeitos (nomes curtos) */
  imunidadesOutras: string[];
  vulnerabilidades: TipoDano[];
  atributos?: Partial<Record<'agi' | 'for' | 'int' | 'pre' | 'vig', number>>;
  /** em metros */
  deslocamento?: number;
  ataques: AtaqueAmeaca[];
  acoes: AcaoAmeacaLivro[];
  /** nomes das habilidades passivas */
  passivas: string[];
  /** imune a todo dano até o enigma de medo ser resolvido */
  enigma?: boolean;
  /** o que, em números, muda a imunidade antes do enigma (vai para as notas da ficha rápida) */
  notaEnigma?: string;
  /** número que o livro imprime de um jeito estranho */
  duvida?: string;
}

