/**
 * Os portadores de relíquia (17/10, o Felipe: "só existe um deles"): o Diabo, o Deus da Morte, a Magistrada e o
 * Anfitrião com as variações dele. Cada um é único na campanha: o Elenco põe um só e recusa o segundo igual enquanto ele
 * estiver em alguma cena. As variações do Anfitrião contam cada uma por si (podem estar todas juntas, uma de cada).
 */
export const PORTADORES_RELIQUIA = ['o-diabo', 'o-deus-da-morte', 'mascara-do-desespero', 'anfitriao', 'anfitriao-amphitruo', 'anfitriao-aeneas', 'anfitriao-liber', 'anfitriao-silenus', 'anfitriao-plautus'];
export const ehPortadorDeReliquia = (livroId?: string) => !!livroId && PORTADORES_RELIQUIA.includes(livroId);
